function readLines(string $path): Generator {
  $h = fopen($path, 'r');
  while (($line = fgets($h)) !== false) {
    yield rtrim($line); // отдаём по одной строке
  }
  fclose($h);
}
foreach (readLines('huge.log') as $line) { /* памяти почти не тратим */ }

function range_lazy(int $n): Generator {
  for ($i = 0; $i < $n; $i++) {
    yield $i; // отдаём по одному, массив не строим
  }
}
foreach (range_lazy(1_000_000) as $i) { /* памяти почти 0 */ }

